import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  rowid: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  /** Epoch milliseconds before which a queued job must not be claimed (retry back-off). */
  run_after: number;
  created_at: string;
  updated_at: string;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  progress_completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  run_after INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue_idx ON jobs (status, run_after);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` inside an immediate (write-locking) transaction. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = fn();
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

export function nowIso(): string {
  return new Date().toISOString();
}

export function getJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function getJobByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY rowid DESC').all() as unknown as JobRow[];
}

export function insertJob(
  db: DatabaseSync,
  job: { id: string; input: string; steps: number; failAttempts: number; idempotencyKey: string | null },
): JobRow {
  const now = nowIso();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(job.id, job.input, job.steps, job.failAttempts, job.idempotencyKey, now, now);
  return getJobById(db, job.id)!;
}

/** Atomically takes the oldest eligible queued job, marks it running and counts the new attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number): JobRow | undefined {
  return transaction(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY rowid LIMIT 1`)
      .get(nowMs) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?`,
    ).run(nowIso(), next.id);
    return getJobById(db, next.id);
  });
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare('UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?').run(completed, nowIso(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
  ).run(output, nowIso(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', progress_completed = 0, result_output = NULL, error = ?, updated_at = ? WHERE id = ?`,
  ).run(error, nowIso(), id);
}

/** Returns a job to the queue so it is picked up again no earlier than `runAfter` (epoch ms). */
export function requeueJob(db: DatabaseSync, id: string, runAfter: number, countAttempt: boolean): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?,
       attempts = CASE WHEN ? THEN attempts ELSE MAX(attempts - 1, 0) END, updated_at = ?
     WHERE id = ?`,
  ).run(runAfter, countAttempt ? 1 : 0, nowIso(), id);
}

/** On worker start: any job left `running` by a dead worker is queued again; its interrupted attempt is not counted. */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  return Number(
    db
      .prepare(
        `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0,
           attempts = MAX(attempts - 1, 0), updated_at = ?
         WHERE status = 'running'`,
      )
      .run(nowIso()).changes,
  );
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat WHERE id = 1').run();
}

export function lastHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return row?.beat_at;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import {
  getJobById,
  getJobByKey,
  insertJob,
  lastHeartbeat,
  listJobs,
  openDatabase,
  transaction,
  type JobRow,
} from './db.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_LIVENESS_MS = 3000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

interface FieldError {
  field: string;
  message: string;
}

interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function toJob(r: JobRow) {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

/** Reads the whole body; resolves to null if it exceeds the size limit. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        resolve(null);
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (!tooLarge) resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  return header.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/** Validates a parsed body. Returns the job to create (defaults applied) or the offending fields. */
function validateBody(raw: string): { ok: true; job: NewJob } | { ok: false; fields: FieldError[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'Body must be valid JSON.' }] };
  }
  if (!isObject(parsed)) return { ok: false, fields: [{ field: 'body', message: 'Body must be a JSON object.' }] };

  const fields: FieldError[] = [];
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  for (const key of Object.keys(parsed)) {
    if (!allowed.has(key)) fields.push({ field: key, message: 'Unknown field.' });
  }

  const { input, steps = DEFAULT_STEPS, failAttempts = DEFAULT_FAIL_ATTEMPTS } = parsed;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string.' });
  } else if (input.length < 1 || input.length > 1000 || input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters and not only whitespace.' });
  }
  if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) {
    fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20.' });
  }
  if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) {
    fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5.' });
  }

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, job: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

function sameJob(row: JobRow, job: NewJob): boolean {
  return row.input === job.input && row.steps === job.steps && row.fail_attempts === job.failAttempts;
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawKey = req.headers['idempotency-key'];
  const key = rawKey === undefined ? undefined : String(rawKey);
  const keyFields: FieldError[] = [];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    keyFields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
  }

  const raw = await readBody(req);
  if (raw === null) {
    return invalid(res, [...keyFields, { field: 'body', message: 'Body is too large.' }]);
  }
  if (!isJsonContentType(req.headers['content-type'])) {
    return invalid(res, [...keyFields, { field: 'body', message: 'Content-Type must be application/json.' }]);
  }
  const result = validateBody(raw);
  if (!result.ok) return invalid(res, [...keyFields, ...result.fields]);
  if (keyFields.length > 0) return invalid(res, keyFields);

  const job = result.job;
  type Outcome = { kind: 'created' | 'replay' | 'conflict'; row?: JobRow };
  const outcome: Outcome = transaction(db, (): Outcome => {
    if (key !== undefined) {
      const existing = getJobByKey(db, key);
      if (existing) return sameJob(existing, job) ? { kind: 'replay', row: existing } : { kind: 'conflict' };
    }
    return { kind: 'created', row: insertJob(db, { id: randomUUID(), ...job, idempotencyKey: key ?? null }) };
  });

  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'replay' ? 200 : 201, toJob(outcome.row!));
}

function handleGetJob(res: ServerResponse, id: string): void {
  const row = getJobById(db, id);
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const beat = lastHeartbeat(db);
  const up = beat !== undefined && Date.now() - beat <= WORKER_LIVENESS_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  let allowed: string[];
  if (path === '/' || path === '/health') allowed = ['GET'];
  else if (path === '/api/jobs') allowed = ['GET', 'POST'];
  else if (/^\/api\/jobs\/[^/]+$/.test(path)) allowed = ['GET'];
  else return sendError(res, 404, 'not_found', 'No such route.');

  if (!allowed.includes(method)) {
    res.setHeader('allow', allowed.join(', '));
    return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`);
  }

  if (path === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    return void res.end(uiHtml);
  }
  if (path === '/health') return handleHealth(res);
  if (path === '/api/jobs') {
    if (method === 'POST') return handleCreateJob(req, res);
    return send(res, 200, { jobs: listJobs(db).map(toJob) });
  }
  let id: string;
  try {
    id = decodeURIComponent(path.slice('/api/jobs/'.length));
  } catch {
    return sendError(res, 404, 'not_found', 'No job with that id.');
  }
  return handleGetJob(res, id);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request error:', e instanceof Error ? e.message : e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  openDatabase,
  recoverInterruptedJobs,
  requeueJob,
  setProgress,
  writeHeartbeat,
  type JobRow,
} from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

let lastBeat = 0;
function beat(force = false): void {
  const now = Date.now();
  if (force || now - lastBeat >= HEARTBEAT_MS) {
    writeHeartbeat(db, now);
    lastBeat = now;
  }
}

/** Runs one attempt of a claimed job (`job.attempts` is already the attempt number). */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: fails at the first step, before any progress.
  if (attempt <= job.fail_attempts) {
    if (attempt >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure');
    else requeueJob(db, job.id, Date.now() + RETRY_DELAY_MS, true);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Shutting down mid-attempt: hand the job back without counting this attempt.
      requeueJob(db, job.id, 0, false);
      return;
    }
    setProgress(db, job.id, step);
    beat();
  }
  completeJob(db, job.id, job.input.toUpperCase());
}

const recovered = recoverInterruptedJobs(db);
beat(true);
console.log(`worker started (requeued ${recovered} interrupted job(s))`);

while (!stopping) {
  try {
    beat();
    const job = claimNextJob(db, Date.now());
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    await runAttempt(job);
  } catch (e) {
    console.error('worker error:', e instanceof Error ? e.message : e);
    await sleep(IDLE_POLL_MS);
  }
}

clearHeartbeat(db);
db.close();
console.log('worker stopped');
