<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Job tracker</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 52rem; padding: 0 1rem; color: #222; }
    form { display: grid; grid-template-columns: 1fr 8rem 10rem; gap: .5rem; align-items: end; }
    label { display: flex; flex-direction: column; font-size: .85rem; gap: .2rem; }
    input { font: inherit; padding: .4rem; }
    button { font: inherit; padding: .4rem 1rem; grid-column: 1 / -1; justify-self: start; }
    [role="alert"] { color: #b00020; min-height: 1.2rem; margin: .75rem 0; }
    [data-testid="job-list"] { list-style: none; padding: 0; }
    [data-testid="job-item"] { border: 1px solid #ccc; border-radius: 6px; padding: .6rem .8rem; margin-bottom: .5rem; display: grid; grid-template-columns: 1fr auto auto; gap: .5rem; align-items: center; }
    [data-testid="job-result"] { grid-column: 1 / -1; font-family: ui-monospace, monospace; word-break: break-all; }
    .status-failed { color: #b00020; }
    .status-completed { color: #17692b; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" maxlength="1000" required>
    </label>
    <label>Steps (1–20)
      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" placeholder="5">
    </label>
    <label>Fail attempts (0–5)
      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" placeholder="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>

  <div data-testid="form-error" role="alert" id="form-error"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    const form = document.getElementById('job-form');
    const inputEl = document.querySelector('[data-testid="job-input"]');
    const stepsEl = document.querySelector('[data-testid="job-steps"]');
    const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
    const errorEl = document.querySelector('[data-testid="form-error"]');
    const listEl = document.querySelector('[data-testid="job-list"]');

    // Numeric text becomes a number so the API validates it; anything else is sent as typed so the API rejects it.
    function toValue(text) {
      const t = text.trim();
      if (/^[-+]?\d+(\.\d+)?$/.test(t)) return Number(t);
      return t;
    }

    function buildPayload() {
      const payload = { input: inputEl.value };
      if (stepsEl.value.trim() !== '') payload.steps = toValue(stepsEl.value);
      if (failEl.value.trim() !== '') payload.failAttempts = toValue(failEl.value);
      return payload;
    }

    function showError(message, fields) {
      const names = (fields || []).map((f) => f.field).join(', ');
      errorEl.textContent = names ? message + ' Fields: ' + names + '.' : message;
    }

    function renderJobs(jobs) {
      listEl.replaceChildren(...jobs.map((job) => {
        const li = document.createElement('li');
        li.setAttribute('data-testid', 'job-item');
        li.dataset.jobId = job.id;

        const label = document.createElement('span');
        label.textContent = job.input;

        const status = document.createElement('span');
        status.setAttribute('data-testid', 'job-status');
        status.className = 'status-' + job.status;
        status.textContent = job.status;

        const progress = document.createElement('span');
        progress.setAttribute('data-testid', 'job-progress');
        progress.textContent = job.progress.completed + '/' + job.progress.total;

        const result = document.createElement('div');
        result.setAttribute('data-testid', 'job-result');
        if (job.status === 'completed') result.textContent = job.result.output;
        else if (job.status === 'failed') result.textContent = job.error;
        else result.textContent = '';

        li.append(label, status, progress, result);
        return li;
      }));
    }

    async function refresh() {
      try {
        const res = await fetch('/api/jobs');
        if (!res.ok) return;
        const body = await res.json();
        renderJobs(body.jobs);
      } catch (_) {
        // Server unreachable; the next poll will retry.
      }
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorEl.textContent = '';
      const button = document.querySelector('[data-testid="job-submit"]');
      button.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(buildPayload()),
        });
        const body = await res.json().catch(() => ({}));
        if (res.ok) {
          inputEl.value = '';
          stepsEl.value = '';
          failEl.value = '';
          await refresh();
        } else {
          const err = body.error || { message: 'Submission failed.' };
          showError(err.message, err.fields);
        }
      } catch (_) {
        errorEl.textContent = 'Could not reach the server.';
      } finally {
        button.disabled = false;
      }
    });

    refresh();
    setInterval(refresh, 1000);
  </script>
</body>
</html>

